/*
 * PLAN
 * 1. COMPOSITION: gradient backdrop plane at z=-2.5; triangular glass prism centered at origin (~1.7u tall read);
 *    red emissive octahedron core inside; caustic streak plane on floor y=-1.1; headline at y=-1.75, caption below.
 * 2. LIGHT RIG (rig-noir-crimson): warm key spot #f4f0ea i58 @ [3,1.8,0.8]; cool/red rim spot #ff2a38 i52 @ [-2.2,1.4,-2]
 *    behind-left so both long prism edges carry rim; red kicker point i5 @ [-1,0.2,1.6]; ambient floor 0.04.
 * 3. MATERIALS: MeshPhysicalNodeMaterial glass — transmission 1.0, ior 1.55, thickness 0.9, iridescence 1.0,
 *    TSL dispersion tint node (0.18 RGB split), attenuation #e8ecf2/2.5; caustic = TSL 3-stop dispersed gradient.
 * 4. MOTION: hover depth-rotate primitive (maxDeg 10); release weighted-settle 1.04->1.0 0.9s power4.out;
 *    idle single slow breathing <=2%; caustic elongates 8% on tilt.
 * 5. FOCAL: the prism (brightest = its red emissive core at 2.2, everything else graded below).
 */
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, color, mix, smoothstep, float, positionLocal, normalWorld, dot, abs as tslAbs } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  const colors = config.intent?.visualSpec?.colors ?? {};
  const C = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#101017',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
    stops: colors.gradientStops ?? [
      { at: 0, hex: '#0b0b10' },
      { at: 0.6, hex: '#12121a' },
      { at: 1, hex: '#16161d' },
    ],
  };

  /* ---------- backdropStage: graded gradient plane, never flat void ---------- */
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const t = uv().y;
    const c0 = color(C.stops[0].hex);
    const c1 = color(C.stops[1].hex);
    const c2 = color(C.stops[2].hex);
    const a0 = float(C.stops[0].at);
    const a1 = float(C.stops[1].at);
    const a2 = float(C.stops[2].at);
    const g = mix(mix(c0, c1, smoothstep(a0, a1, t)), c2, smoothstep(a1, a2, t));
    // faint red atmospheric bloom low-center so the stage breathes (ink/surface grade)
    const cx = uv().x.sub(0.5);
    const glow = smoothstep(0.55, 0.0, cx.mul(cx).add(uv().y.sub(0.28).mul(uv().y.sub(0.28))).sqrt());
    backdropMat.colorNode = g.add(color(C.accent).mul(glow.mul(0.045))).add(color(C.surface).mul(0.12));
  }
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  /* ---------- prismSubject: dispersive glass prism ---------- */
  const prismPivot = new THREE.Group();
  group.add(prismPivot);

  // Equilateral triangular cross-section, 1.2 units per side, length 1.8, axis horizontal
  const side = 1.2;
  const triShape = new THREE.Shape();
  const h = side * Math.sqrt(3) / 2;
  triShape.moveTo(-side / 2, -h / 3);
  triShape.lineTo(side / 2, -h / 3);
  triShape.lineTo(0, (2 * h) / 3);
  triShape.closePath();
  const prismGeo = new THREE.ExtrudeGeometry(triShape, { depth: 1.8, bevelEnabled: true, bevelThickness: 0.02, bevelSize: 0.02, bevelSegments: 2 });
  prismGeo.center();

  const glassMat = new MeshPhysicalNodeMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    metalness: 0.0,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    attenuationColor: new THREE.Color(C.paper),
    attenuationDistance: 2.5,
    transparent: true,
    side: THREE.DoubleSide,
  });
  // TSL dispersion pass: split refraction tint by 0.18 across RGB along view-grazing angle
  {
    const fres = float(1.0).sub(tslAbs(dot(normalWorld, vec3(0, 0, 1)))).clamp(0, 1);
    const split = float(0.18);
    const r = smoothstep(float(0.0), float(1.0), fres.add(split));
    const gch = smoothstep(float(0.0), float(1.0), fres);
    const b = smoothstep(float(0.0), float(1.0), fres.sub(split));
    glassMat.emissiveNode = vec3(r, gch, b).mul(fres.pow(2.0)).mul(0.35);
  }
  const prism = new THREE.Mesh(prismGeo, glassMat);
  prismPivot.add(prism);
  prismPivot.rotation.z = THREE.MathUtils.degToRad(12);
  prismPivot.rotation.y = THREE.MathUtils.degToRad(20);
  disposables.push(prismGeo, glassMat);

  /* ---------- emissiveCore: red octahedron inside prism ---------- */
  const coreGeo = new THREE.OctahedronGeometry(0.35);
  const coreMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(C.accent),
    emissive: new THREE.Color(C.accent),
    emissiveIntensity: 2.2,
    roughness: 0.4,
    metalness: 0.0,
  });
  const core = new THREE.Mesh(coreGeo, coreMat);
  prismPivot.add(core);
  disposables.push(coreGeo, coreMat);

  /* ---------- lightRig: rig-noir-crimson (node-local) ---------- */
  const key = new THREE.SpotLight(0xf4f0ea, 58, 0, 0.42, 0.3, 2);
  key.position.set(3, 1.8, 0.8);
  key.target.position.set(0, 0.5, 0);
  group.add(key, key.target);

  const rim = new THREE.SpotLight(new THREE.Color(C.accent).getHex(), 52, 0, 0.55, 0.5, 2);
  rim.position.set(-2.2, 1.4, -2);
  rim.target.position.set(0, 0.6, 0);
  group.add(rim, rim.target);

  const kicker = new THREE.PointLight(new THREE.Color(C.accent).getHex(), 5, 6, 2);
  kicker.position.set(-1, 0.2, 1.6);
  group.add(kicker);

  const ambientFloor = new THREE.AmbientLight(0xffffff, 0.04);
  group.add(ambientFloor);

  /* ---------- causticStreak: dispersed floor gradient plane ---------- */
  const causticGeo = new THREE.PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const x = uv().x;
    const cA = color('#ff2a38');
    const cB = color(C.paper);
    const cC = color('#9fb0c4');
    const grad = mix(mix(cA, cB, smoothstep(0.2, 0.5, x)), cC, smoothstep(0.5, 0.8, x));
    const edge = smoothstep(0.0, 0.15, x).mul(smoothstep(1.0, 0.85, x));
    const vEdge = smoothstep(0.0, 0.35, uv().y).mul(smoothstep(1.0, 0.65, uv().y));
    causticMat.colorNode = grad;
    causticMat.opacityNode = edge.mul(vEdge).mul(0.35);
  }
  const caustic = new THREE.Mesh(causticGeo, causticMat);
  caustic.rotation.x = -Math.PI / 2;
  caustic.position.set(0, -1.1, 0.3);
  group.add(caustic);
  disposables.push(causticGeo, causticMat);

  // contact shadow under prism
  const shadowGeo = new THREE.CircleGeometry(1.3, 32);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = smoothstep(1.0, 0.0, uv().sub(0.5).length().mul(2.0)).mul(0.5);
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -1.11;
  group.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  /* ---------- textBlock: MSDF headline + caption ---------- */
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? { text: 'Light, machined.' };
  const captionItem = items.find((i) => i.role === 'caption') ?? { text: 'SAPPHIRE OVER DIAL / ZERO DISTORTION' };

  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: headlineItem.typography?.fontSize ?? 68,
    color: C.paper,
    align: 'center',
  });
  headline.position.set(0, -1.75, 0.4);
  group.add(headline);

  const caption = ctx.fontAtlas.createText(captionItem.text, {
    fontSize: captionItem.typography?.fontSize ?? 18,
    color: '#9fb0c4',
    align: 'center',
    letterSpacingPx: 1.5,
  });
  caption.position.set(0, -2.25, 0.4);
  group.add(caption);

  /* ---------- motion: entrance + idle breathing + weighted settle ---------- */
  const entrance = gsap.timeline();
  entrance.from(prismPivot.position, { y: -0.35, duration: 0.7, ease: 'power3.out' });
  entrance.from(headline.position, { y: '-=0.3', duration: 0.7, ease: 'power3.out' }, 0.1);
  entrance.fromTo(prismPivot.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.4);
  timelines.push(entrance);

  const idle = gsap.timeline({ repeat: -1, yoyo: true });
  idle.to(core.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 3.2, ease: 'sine.inOut' });
  timelines.push(idle);

  /* ---------- primitivesApply: EVERY config.cinematicPrimitives ---------- */
  for (const p of config.cinematicPrimitives ?? []) {
    const handle = ctx.primitives[p.name](prismPivot, p.params ?? {});
    if (handle) primitiveHandles.push(handle);
  }

  /* ---------- handlers: hover elongates caustic 8%, release weighted-settle ---------- */
  group.userData.handlers = {
    hover: () => {
      const t = gsap.to(caustic.scale, { x: 1.08, duration: 0.35, ease: 'power2.out' });
      timelines.push(t);
    },
    unhover: () => {
      const t = gsap.timeline();
      t.to(caustic.scale, { x: 1.0, duration: 0.9, ease: 'power4.out' }, 0);
      t.fromTo(prismPivot.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
      timelines.push(t);
    },
  };

  group.userData.cleanup = () => {
    for (const t of timelines) t.kill();
    for (const h of primitiveHandles) h.cleanup && h.cleanup();
    for (const d of disposables) d.dispose && d.dispose();
    key.dispose && key.dispose();
    rim.dispose && rim.dispose();
    kicker.dispose && kicker.dispose();
  };

  return group;
}

/* @spec-manifest
{"elements":[
{"id":"text.headline.0","where":"textBlock","how":"fontAtlas headline at y=-1.75"},
{"id":"text.caption.1","where":"textBlock","how":"fontAtlas mono caption below headline"},
{"id":"color.background","where":"backdropStage","how":"gradient stop 0 #0b0b10"},
{"id":"color.surface","where":"backdropStage","how":"surface tint added to backdrop grade"},
{"id":"color.ink","where":"backdropStage","how":"gradient stop 1.0 #16161d"},
{"id":"color.paper","where":"textBlock","how":"headline color and glass attenuationColor"},
{"id":"color.accent","where":"emissiveCore","how":"red core, rim, kicker, caustic stop"},
{"id":"color.gradient","where":"backdropStage","how":"3-stop vertical TSL gradient"},
{"id":"effects.spec","where":"prismSubject","how":"1.2-side extruded prism, dispersion, iridescence, caustic"},
{"id":"primitive.depth-rotate","where":"primitivesApply","how":"ctx.primitives loop on prismPivot"}
]}
*/
